mapper.select:
select p.*,s.name as species_val,o.organization_name,u.user_name,i.indicator_name,ps.name as ps_name
from tb_project p
left join tb_project_member m on p.project_id = m.project_id
left join tb_species s on p.species_id = s.species_id
left join sys_organization o on p.organization_id = o.organization_id
left join sys_user u on p.create_by = u.user_id
left join tb_pathological_indicator i on p.tag_id = i.indicator_id
left join tb_product_series ps on p.product_series_id = ps.product_series_id


        AND m.user_id = #{params.userId}


        AND p.project_name like CONCAT('%',#{params.projectName},'%')


        AND p.product_series_id = #{params.productSeriesId}


        AND p.species_id = #{params.speciesId}


        AND p.project_type = #{params.projectType}


        AND p.create_by = #{params.createBy}


        AND p.status = #{params.status}


        AND p.color_type = #{params.colorType}


        and date_format(m.create_time,'%y%m%d') >= date_format(#{params.start},'%y%m%d')


        and date_format(m.create_time,'%y%m%d') <= date_format(#{params.end},'%y%m%d')

